      this.domElement.innerHTML = [
        '<div class="elb-container dhl-spfx-fullscreen" style="width: 100%; min-height: 100vh; margin: 0; padding: 0;">',
        "\r\n\r\n  <!-- Navbar Clean DHL Supply Chain -->\r\n  <nav class=\"top-nav\">\r\n    <div id=\"brandHomeLink\" class=\"brand-group\" data-csp-onclick=\"irParaConferencia()\" style=\"cursor: pointer;\" title=\"Ir para Conferência de Stage\">\r\n      <svg height=\"32\" viewBox=\"0 0 196 43.2533\" width=\"145\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block; border-radius:4px;\"><path d=\"m0 0h196v43.2533h-196z\" fill=\"#fc0\"/><g fill=\"#d40511\"><path d=\"m0 29.901h26.506l-1.448 1.97h-25.058z\"/><path d=\"m0 26.245h29.199l-1.451 1.968h-27.748z\"/><path d=\"m0 33.56h23.815l-1.442 1.956h-22.373z\"/><path d=\"m196 31.871h-26.402l1.447-1.969h24.955z\"/><path d=\"m196 35.516-29.087.003 1.441-1.959h27.646z\"/><path d=\"m173.735 26.245h22.265v1.969l-23.713.002z\"/><path d=\"m25.6726 35.5163 12.5779-17.0888h15.6082c1.7252 0 1.7026.655.86 1.7975-.8562 1.16-2.3133 3.1547-3.1854 4.3323-.4426.5982-1.2431 1.6881 1.4089 1.6881h20.91c-1.739 2.3822-7.38 9.2709-17.5082 9.2709z\"/><path d=\"m97.7056 26.244-6.82 9.2723h-17.9926s6.8172-9.2709 6.8233-9.2709z\"/><path d=\"m123.7239 26.2454-6.8239 9.2709h-17.9857s6.8178-9.2709 6.8239-9.2709z\"/><path d=\"m129.5749 26.2454c.0006 0-1.3141 1.7975-1.9529 2.66-2.2593 3.0534-.2626 6.6105 7.111 6.6105h28.8853l6.8226-9.2709z\"/><path d=\"m34.4685 7.8007-6.2621 8.508h34.1289c1.7249 0 1.7023.655.8592 1.7974-.8562 1.1587-2.2894 3.1763-3.1614 4.3539-.4427.597-1.2432 1.6867 1.4089 1.6867h13.9564s2.25-3.0615 4.1352-5.6206c2.5655-3.4815.2225-10.7254-8.9486-10.7254z\"/><path d=\"m125.269 24.147h-44.007l12.034-16.346h17.986l-6.896 9.372h8.028l6.901-9.372h17.984z\"/><path d=\"m162.2084 7.8007-12.0314 16.346h-19.0593s12.0355-16.346 12.0415-16.346z\"/></g></svg>\r\n      <div class=\"nav-divider\"></div>\r\n      <div class=\"nav-titles\">\r\n        <span class=\"nav-app-name\">Conferência de Stage</span>\r\n        <span class=\"nav-app-sub\">DHL Supply Chain • Expedição</span>\r\n      </div>\r\n    </div>\r\n    <div class=\"nav-actions\">\r\n      <button id=\"btnNavConferencia\" class=\"btn-icon-nav\" title=\"Tela de Conferência de Stage (Scanner / Embarque)\" data-csp-onclick=\"irParaConferencia()\">\r\n        Conferência\r\n      </button>\r\n      <button id=\"btnToggleDashboard\" class=\"btn-icon-nav btn-nav-dash\" title=\"Mapa Visual de Stages e Gestão de Pátio\" data-csp-onclick=\"toggleDashboard()\">\r\n        Mapa de Stages\r\n      </button>\r\n      <button id=\"btnOperacao3D\" class=\"btn-icon-nav\" title=\"Visualização de Pátio em 3D Frontal\" data-csp-onclick=\"abrirOperacao3D()\">\r\n        Operação 3D\r\n      </button>\r\n      <button id=\"btnToggleConsolidacao\" class=\"btn-icon-nav btn-nav-consolidacao\" title=\"Consolidação de Paletes por SKU+Lote\" data-csp-onclick=\"toggleConsolidacao()\">\r\n        Consolidação\r\n      </button>\r\n      <button id=\"btnUploadModal\" class=\"btn-icon-nav\" title=\"Importar / Atualizar Planilha Excel (.xlsx)\" data-csp-onclick=\"openUploadModal()\">\r\n        Atualizar Base\r\n      </button>\r\n      <button id=\"btnNavAnalytics\" class=\"btn-icon-nav\" title=\"Dashboard Operacional & Oportunidades (Dias, Horários, Usuários, Embarques, Docas, Stages)\" data-csp-onclick=\"abrirAnalyticsDashboard()\">\r\n        📈 Dashboard\r\n      </button>\r\n      <button id=\"btnPowerBiModal\" class=\"btn-icon-nav\" title=\"Sincronização Direta via API Live do Power BI\" data-csp-onclick=\"openPowerBiModal()\">\r\n        Power BI\r\n      </button>\r\n      <button id=\"btnNavPbiWeb\" class=\"btn-icon-nav\" style=\"border-color:#BFDBFE; color:#003DA5; background:rgba(0,61,165,0.06); font-weight:700;\" title=\"Abrir Relatório AD HOC 80 Oficial no Power BI (Visualizar / Exportar)\" data-csp-onclick=\"abrirModalPowerBiIframe()\">\r\n        📊 Power BI Web\r\n      </button>\r\n      <button id=\"btnVerHistorico\" class=\"btn-icon-nav\" title=\"Histórico da Ferramenta\" data-csp-onclick=\"openHistoryModal('conf')\">\r\n        Histórico (<span id=\"navHistCount\">0</span>)\r\n      </button>\r\n      <button id=\"btnSoundToggle\" class=\"btn-icon-nav\" title=\"Alternar Som\">\r\n        <span id=\"soundIcon\">🔊</span>\r\n      </button>\r\n      <div id=\"navBaseCount\" class=\"nav-status-chip\" data-csp-onclick=\"document.getElementById('modalBase').style.display='flex'\" style=\"cursor: pointer;\" title=\"Clique para ver detalhes da base\">Base: ...</div>\r\n      <div id=\"navSyncStatus\" class=\"nav-sync-chip\" data-csp-onclick=\"openSyncModal()\" title=\"Sincronização em Tempo Real (On-Time)\">\r\n        <span id=\"syncStatusDot\" class=\"sync-status-dot online\"></span>\r\n        <span id=\"syncStatusText\">On-Time</span>\r\n        <span id=\"syncPeersCount\" class=\"sync-peers-badge\" style=\"display:none;\" title=\"Dispositivos conectados em tempo real\">1</span>\r\n      </div>\r\n    </div>\r\n  </nav>\r\n\r\n  <!-- =========================================================\r\n       TELA 1: LOGIN DO EMBARQUE (DHL CLEAN & ORGANIZADO)\r\n       ========================================================= -->\r\n  <main id=\"viewLogin\" class=\"login-screen\">\r\n    <div class=\"clean-login-card\" style=\"border-top: 5px solid var(--dhl-red); border-bottom: 3px solid var(--dhl-yellow); box-shadow: 0 10px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.03);\">\r\n      <div style=\"display: flex; justify-content: center; margin-bottom: 14px;\">\r\n        <svg height=\"32\" viewBox=\"0 0 196 43.2533\" width=\"145\" xmlns=\"http://www.w3.org/2000/svg\" style=\"display:block; border-radius:4px;\"><path d=\"m0 0h196v43.2533h-196z\" fill=\"#fc0\"/><g fill=\"#d40511\"><path d=\"m0 29.901h26.506l-1.448 1.97h-25.058z\"/><path d=\"m0 26.245h29.199l-1.451 1.968h-27.748z\"/><path d=\"m0 33.56h23.815l-1.442 1.956h-22.373z\"/><path d=\"m196 31.871h-26.402l1.447-1.969h24.955z\"/><path d=\"m196 35.516-29.087.003 1.441-1.959h27.646z\"/><path d=\"m173.735 26.245h22.265v1.969l-23.713.002z\"/><path d=\"m25.6726 35.5163 12.5779-17.0888h15.6082c1.7252 0 1.7026.655.86 1.7975-.8562 1.16-2.3133 3.1547-3.1854 4.3323-.4426.5982-1.2431 1.6881 1.4089 1.6881h20.91c-1.739 2.3822-7.38 9.2709-17.5082 9.2709z\"/><path d=\"m97.7056 26.244-6.82 9.2723h-17.9926s6.8172-9.2709 6.8233-9.2709z\"/><path d=\"m123.7239 26.2454-6.8239 9.2709h-17.9857s6.8178-9.2709 6.8239-9.2709z\"/><path d=\"m129.5749 26.2454c.0006 0-1.3141 1.7975-1.9529 2.66-2.2593 3.0534-.2626 6.6105 7.111 6.6105h28.8853l6.8226-9.2709z\"/><path d=\"m34.4685 7.8007-6.2621 8.508h34.1289c1.7249 0 1.7023.655.8592 1.7974-.8562 1.1587-2.2894 3.1763-3.1614 4.3539-.4427.597-1.2432 1.6867 1.4089 1.6867h13.9564s2.25-3.0615 4.1352-5.6206c2.5655-3.4815.2225-10.7254-8.9486-10.7254z\"/><path d=\"m125.269 24.147h-44.007l12.034-16.346h17.986l-6.896 9.372h8.028l6.901-9.372h17.984z\"/><path d=\"m162.2084 7.8007-12.0314 16.346h-19.0593s12.0355-16.346 12.0415-16.346z\"/></g></svg>\r\n      </div>\r\n      <div style=\"text-align: center; margin-bottom: 18px;\">\r\n        <span class=\"dhl-badge-tag\" style=\"margin-bottom: 8px;\">DHL SUPPLY CHAIN • EXPEDIÇÃO</span>\r\n        <h2 class=\"clean-login-title\" style=\"margin: 4px 0 6px; font-size: 1.3rem;\">Conferência de Stage</h2>\r\n        <p class=\"clean-login-desc\" style=\"margin: 0; font-size: 0.82rem;\">Informe o número do embarque e seu nome para iniciar.</p>\r\n      </div>\r\n\r\n      <div class=\"form-field\">\r\n        <label for=\"inputEmbarque\" style=\"font-weight: 700; color: #1E293B; font-size: 0.85rem;\">📦 Número do Embarque:</label>\r\n        <input type=\"text\" id=\"inputEmbarque\" class=\"input-clean\" \r\n               placeholder=\"Digite ou bipe o embarque...\" \r\n               autofocus autocomplete=\"off\" spellcheck=\"false\"\r\n               style=\"font-size: 1.05rem; padding: 12px; font-weight: 700; border-radius: 8px;\">\r\n      </div>\r\n\r\n      <div class=\"form-field\" style=\"margin-bottom: 22px;\">\r\n        <label for=\"inputOperador\" style=\"font-weight: 700; color: #1E293B; font-size: 0.85rem;\">👤 Operador / Conferente:</label>\r\n        <input type=\"text\" id=\"inputOperador\" class=\"input-clean\" \r\n               style=\"font-size: 0.95rem; padding: 12px; border-radius: 8px;\" \r\n               value=\"\" placeholder=\"Digite seu nome (obrigatório)...\" autocomplete=\"name\">\r\n      </div>\r\n\r\n      <button id=\"btnLogin\" class=\"btn-clean-primary\" style=\"padding: 14px; font-size: 1rem; font-weight: 800; border-radius: 8px; transition: all 0.2s; cursor: pointer;\">\r\n        ✔ Iniciar Conferência [ENTER]\r\n      </button>\r\n\r\n      <div style=\"margin-top: 18px; text-align: center; border-top: 1px solid var(--border-light); padding-top: 12px;\">\r\n        <button id=\"btnQuickUpload\" class=\"btn-link-action\" style=\"font-size: 0.78rem;\">\r\n          📁 Ou clique aqui para carregar novo arquivo Excel (.xlsx)\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </main>\r\n\r\n  <!-- =========================================================\r\n       TELA 2: ÁREA DE BIPAGEM CONTÍNUA DE LPN\r\n       ========================================================= -->\r\n  <main id=\"viewScanner\" class=\"main-wrapper\" style=\"display: none;\">\r\n\r\n    <!-- Summary KPI Card com Embarque em Gradiente e Gráfico Interativo de Conclusão -->\r\n    <section class=\"shipment-header-card\">\r\n      <div class=\"shipment-header-left\">\r\n        <!-- Destaque Colorido do Embarque com Gradiente -->\r\n        <div class=\"kpi-unit kpi-unit-embarque\">\r\n          <span class=\"caption\">Embarque Ativo</span>\r\n          <div class=\"embarque-badge-gradient\" id=\"badgeEmbarqueGradient\">\r\n            <span class=\"emb-badge-icon\">📦</span>\r\n            <span id=\"txtEmbarque\" class=\"metric-emb\">-</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"kpi-cluster\">\r\n          <div class=\"kpi-unit\">\r\n            <span class=\"caption\">Stage Sistêmico</span>\r\n            <span id=\"txtStage\" class=\"metric\">-</span>\r\n          </div>\r\n          <div class=\"kpi-unit\">\r\n            <span class=\"caption\">Stage Físico Atual</span>\r\n            <span id=\"txtStageFisico\" class=\"metric blue\">-</span>\r\n          </div>\r\n          <div class=\"kpi-unit\">\r\n            <span class=\"caption\">Físico x Sistêmico</span>\r\n            <div id=\"txtStatusFisicoSistemico\" class=\"badge-fisico-sistemico idle\">\r\n              ⚪ Aguardando Leitura\r\n            </div>\r\n          </div>\r\n          <div class=\"kpi-unit\">\r\n            <span class=\"caption\">Total</span>\r\n            <span id=\"txtTotalPaletes\" class=\"metric\">0</span>\r\n          </div>\r\n          <div class=\"kpi-unit\">\r\n            <span class=\"caption\">Conferidos</span>\r\n            <span id=\"txtConferidos\" class=\"metric green\">0</span>\r\n          </div>\r\n          <div class=\"kpi-unit\">\r\n            <span class=\"caption\">Pendentes</span>\r\n            <span id=\"txtPendentes\" class=\"metric orange\">0</span>\r\n          </div>\r\n          <div class=\"kpi-unit\">\r\n            <span class=\"caption\">Divergências</span>\r\n            <span id=\"txtDivergencias\" class=\"metric red\">0</span>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Painel de Operação Inteligente (Power BI Live: Transportadora / Carreta / Janela Doca) -->\r\n        <div class=\"shipment-smart-meta\" id=\"shipmentSmartMeta\" style=\"display: flex; align-items: center; gap: 14px; flex-wrap: wrap; margin-top: 8px; padding-top: 8px; border-top: 1px solid rgba(0,0,0,0.06); font-size: 0.8rem;\">\r\n          <div style=\"display: flex; align-items: center; gap: 5px;\">\r\n            <span style=\"opacity: 0.65;\">🚛 Transportadora:</span>\r\n            <b id=\"txtSmartTransportadora\" style=\"color: #1E293B;\">-</b>\r\n          </div>\r\n          <div style=\"display: flex; align-items: center; gap: 5px;\">\r\n            <span style=\"opacity: 0.65;\">🏷️ Placa/Carreta:</span>\r\n            <b id=\"txtSmartPlaca\" style=\"background: #E2E8F0; padding: 1px 6px; border-radius: 4px; font-family: monospace;\">-</b>\r\n          </div>\r\n          <div style=\"display: flex; align-items: center; gap: 5px;\">\r\n            <span style=\"opacity: 0.65;\">⏱️ Janela Doca:</span>\r\n            <b id=\"txtSmartJanela\" style=\"color: #0284C7;\">-</b>\r\n          </div>\r\n          <div id=\"badgeSmartPrioridade\" style=\"display: inline-flex; align-items: center; gap: 4px; padding: 2px 8px; border-radius: 12px; font-weight: 700; font-size: 0.72rem; background: #E2E8F0; color: #475569;\">\r\n            ⚡ Carreta: Operacional\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Gráfico Interativo de Conclusão com Gradiente -->\r\n      <div class=\"header-completion-widget\" id=\"headerCompletionWidget\" data-csp-onclick=\"toggleCompletionPopover(event)\" title=\"Clique para ver o raio-x da conclusão do embarque\">\r\n        <div class=\"radial-chart-box\">\r\n          <svg class=\"radial-chart-svg\" viewBox=\"0 0 84 84\">\r\n            <defs>\r\n              <linearGradient id=\"headerCompletionGrad\" x1=\"0%\" y1=\"100%\" x2=\"100%\" y2=\"0%\">\r\n                <stop offset=\"0%\" stop-color=\"#FFCC00\" />\r\n                <stop offset=\"45%\" stop-color=\"#FF7A00\" />\r\n                <stop offset=\"100%\" stop-color=\"#00A650\" />\r\n              </linearGradient>\r\n            </defs>\r\n            <circle class=\"radial-track\" cx=\"42\" cy=\"42\" r=\"36\" fill=\"transparent\" />\r\n            <circle id=\"radialProgressRing\" class=\"radial-progress\" cx=\"42\" cy=\"42\" r=\"36\" fill=\"transparent\"\r\n                    stroke=\"url(#headerCompletionGrad)\" stroke-dasharray=\"226.2\" stroke-dashoffset=\"226.2\" />\r\n          </svg>\r\n          <div class=\"radial-center-content\">\r\n            <span id=\"radialPercentText\" class=\"radial-percent-num\">0%</span>\r\n            <span class=\"radial-percent-lbl\">CONCLUÍDO</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"radial-meta-col\">\r\n          <span class=\"radial-meta-title\">Conclusão da Carga</span>\r\n          <span id=\"radialStatusLabel\" class=\"radial-meta-status\">AGUARDANDO</span>\r\n          <span id=\"radialCountsText\" class=\"radial-meta-sub\">0 de 0 paletes</span>\r\n          <span class=\"btn-open-popover\">Raio-X Interativo ▾</span>\r\n        </div>\r\n\r\n        <!-- Popover Interativo Flutuante com Gradiente e Estatísticas -->\r\n        <div class=\"completion-popover\" id=\"completionPopover\">\r\n          <div class=\"popover-header\">\r\n            <span>⚡ Raio-X de Conclusão</span>\r\n            <span id=\"popoverPercentBadge\" class=\"popover-badge\">0%</span>\r\n          </div>\r\n          <div class=\"popover-row\">\r\n            <span>✔ Paletes Conferidos:</span>\r\n            <b id=\"popoverConf\">0</b>\r\n          </div>\r\n          <div class=\"popover-row\">\r\n            <span>⏳ Paletes Pendentes:</span>\r\n            <b id=\"popoverPend\">0</b>\r\n          </div>\r\n          <div class=\"popover-row\">\r\n            <span>📦 Total da Carga:</span>\r\n            <b id=\"popoverTotal\">0</b>\r\n          </div>\r\n          <div class=\"popover-row\">\r\n            <span>⚠️ Divergências:</span>\r\n            <b id=\"popoverDiv\" style=\"color: #DC2626;\">0</b>\r\n          </div>\r\n          <div class=\"popover-bar-wrap\">\r\n            <div class=\"popover-bar-fill\" id=\"popoverProgressFill\" style=\"width: 0%;\"></div>\r\n          </div>\r\n          <div class=\"popover-footer-tip\">\r\n            Clique no gráfico para fechar\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"header-action-buttons\">\r\n        <button id=\"btnScannerConsolidacao\" class=\"btn-ghost-switch\" style=\"color: #6D28D9; border-color: #DDD6FE; font-weight: 800;\" data-csp-onclick=\"toggleConsolidacao()\" title=\"Ver cubagem e consolidação deste embarque\">\r\n          🔗 Consolidar Carga\r\n        </button>\r\n        <button id=\"btnReiniciarConferencia\" class=\"btn-ghost-switch\" title=\"Zerar bipagens deste embarque e recomeçar\">\r\n          🔄 Reiniciar\r\n        </button>\r\n        <button id=\"btnTrocarEmbarque\" class=\"btn-ghost-switch\">\r\n          ↩ Trocar Embarque\r\n        </button>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- Grid das Posições Físicas do Stage Ativo -->\r\n    <section id=\"stageSlotsCard\" class=\"stage-slots-card\">\r\n      <div class=\"slots-header\">\r\n        <div class=\"slots-title-group\">\r\n          <span class=\"slots-title\">Alocação de Posições no Stage</span>\r\n          <span id=\"txtStageSlotsSubtitle\" class=\"slots-sub\">Sequenciamento contínuo de vagas</span>\r\n        </div>\r\n        <div class=\"slots-actions\">\r\n          <div class=\"capacity-selector\">\r\n            <span class=\"cap-label\">Vagas:</span>\r\n            <button type=\"button\" class=\"btn-cap-pill\" data-cap=\"6\" data-csp-onclick=\"setStageCapacity(6)\">6</button>\r\n            <button type=\"button\" class=\"btn-cap-pill\" data-cap=\"8\" data-csp-onclick=\"setStageCapacity(8)\">8</button>\r\n            <button type=\"button\" class=\"btn-cap-pill active\" data-cap=\"10\" data-csp-onclick=\"setStageCapacity(10)\">10</button>\r\n          </div>\r\n          <button id=\"btnInverterSentido\" class=\"btn-slots-tool\" data-csp-onclick=\"toggleSlotDirection()\" title=\"Alternar entre ordem crescente ou decrescente\">\r\n            Inverter Sentido\r\n          </button>\r\n          <button id=\"btnPularVaga\" class=\"btn-slots-tool\" data-csp-onclick=\"skipCurrentSlot()\" title=\"Pular a vaga atual para a próxima\">\r\n            Pular Vaga\r\n          </button>\r\n          <button id=\"btnModoEmpilhamento\" class=\"btn-slots-tool\" style=\"font-weight: 800; background: #EEF2FF; border-color: #6366F1; color: #4338CA;\" data-csp-onclick=\"toggleModoEmpilhamento()\" title=\"Alternar modo de carga: 1 Palete/Vaga, 2 Paletes Duplados (empilhados) ou Fracionado (até 3 na mesma vaga)\">\r\n            🥞 Carga: Padrão (1x)\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Barra de seleção rápida de Stages do Embarque -->\r\n      <div id=\"shipmentStagesSelector\" class=\"shipment-stages-bar\" style=\"display: none;\"></div>\r\n\r\n      <div id=\"stageSlotsGrid\" class=\"stage-slots-grid\"></div>\r\n      <div class=\"slots-legend\">\r\n        <span class=\"legend-item\"><span class=\"swatch swatch-free\"></span> <b>Cinza:</b> Livre</span>\r\n        <span class=\"legend-item\"><span class=\"swatch swatch-target\"></span> <b>Azul:</b> Bipando Agora</span>\r\n        <span class=\"legend-item\"><span class=\"swatch swatch-done\"></span> <b>Verde:</b> Conferido (1 plt)</span>\r\n        <span class=\"legend-item\"><span class=\"swatch swatch-duplado\" style=\"background:#7C3AED;\"></span> <b>Roxo:</b> Duplado (2 plts 🥞)</span>\r\n        <span class=\"legend-item\"><span class=\"swatch swatch-fracionado\" style=\"background:#EA580C;\"></span> <b>Laranja:</b> Fracionado (3 plts 📦)</span>\r\n        <span class=\"legend-item\"><span class=\"swatch swatch-waiting\"></span> <b>Cinza Claro:</b> Na Fila</span>\r\n        <span class=\"legend-item\"><span class=\"swatch swatch-divergent\"></span> <b>Vermelho:</b> Bloqueado / Divergência (✖)</span>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- Scanner Card Minimalista -->\r\n    <section id=\"scannerCard\" class=\"scan-card\">\r\n      <div class=\"scan-card-label\">\r\n        <span>⚡ Bipagem de LPN ou Stage Físico</span>\r\n        <span class=\"badge-live-dot\">\r\n          <span class=\"pulse-circle\"></span> Leitura Automática\r\n        </span>\r\n      </div>\r\n\r\n      <input type=\"text\" id=\"barcodeInput\" class=\"scan-input-ultra\" \r\n             placeholder=\"Bipe a LPN do palete ou a placa do Stage (ex: ST008 ou SO008)...\" \r\n             autocomplete=\"off\" spellcheck=\"false\">\r\n\r\n      <!-- Feedback Banner Discreto -->\r\n      <div id=\"feedbackBanner\" class=\"clean-feedback\">\r\n        <span id=\"feedbackIcon\" style=\"font-size: 1.1rem; line-height: 1;\"></span>\r\n        <div id=\"feedbackText\" style=\"flex: 1;\"></div>\r\n      </div>\r\n\r\n    </section>\r\n\r\n    <!-- =========================================================\r\n         PAINEL DE AMOSTRAGEM 10% — Controle de Qualidade P&G\r\n         ========================================================= -->\r\n    <section id=\"amostragemCard\" class=\"amostragem-card\" style=\"display: none;\">\r\n      <div class=\"amostragem-header\" data-csp-onclick=\"toggleAmostragemPanel()\">\r\n        <div class=\"amostragem-title-group\">\r\n          <span class=\"amostragem-icon\">🎲</span>\r\n          <div>\r\n            <span class=\"amostragem-title\">Amostragem de Controle — 10% da Carga</span>\r\n            <span id=\"amostragemStatus\" class=\"amostragem-subtitle\">Carregando amostra...</span>\r\n          </div>\r\n        </div>\r\n        <div style=\"display: flex; align-items: center; gap: 10px;\">\r\n          <div id=\"amostragemProgressPill\" class=\"amostragem-pill\">0/0</div>\r\n          <button class=\"amostragem-toggle-btn\" id=\"btnAmostragemToggle\">▼</button>\r\n        </div>\r\n      </div>\r\n      <div id=\"amostragemBody\" class=\"amostragem-body\">\r\n        <div id=\"amostragemList\" class=\"amostragem-list\"></div>\r\n        <div class=\"amostragem-footer\">\r\n          <button class=\"btn-amostragem-nova\" data-csp-onclick=\"gerarNovaAmostragem()\">🔀 Gerar Nova Amostra</button>\r\n          <span class=\"amostragem-footer-note\">Paletes selecionados aleatoriamente • Mínimo 10% por embarque</span>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n\r\n    <!-- Progresso Slim -->\r\n    <section class=\"progress-card-slim\">\r\n      <div class=\"progress-text-row\">\r\n        <span>Progresso da Conferência</span>\r\n        <span id=\"progressPercent\" style=\"color: var(--text-primary);\">0% (0 de 0 paletes)</span>\r\n      </div>\r\n      <div class=\"progress-track-slim\">\r\n        <div id=\"progressFill\" class=\"progress-fill-slim\"></div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- Painel Duplo: Distribuição dos Paletes no Stage & Histórico em Tempo Real -->\r\n    <section class=\"paletes-stage-card\">\r\n      <div class=\"paletes-stage-tabs-bar\">\r\n        <button id=\"tabBtnDistribuicao\" class=\"tab-paletes-btn active\" data-csp-onclick=\"switchPaletesTab('distribuicao')\">\r\n          📦 Distribuição nos Stages (<span id=\"tabCountTotalPaletes\">0</span>)\r\n        </button>\r\n        <button id=\"tabBtnHistorico\" class=\"tab-paletes-btn\" data-csp-onclick=\"switchPaletesTab('historico')\">\r\n          📜 Histórico de Bipagens (<span id=\"tabCountHistorico\">0</span>)\r\n        </button>\r\n      </div>\r\n\r\n      <!-- TAB 1: Distribuição de Paletes no Stage (Mostra onde cada palete está alocado: ex SO01A, SO02B) -->\r\n      <div id=\"tabContentDistribuicao\" class=\"paletes-tab-content active\">\r\n        <div class=\"distribuicao-toolbar\">\r\n          <div class=\"distribuicao-filters\">\r\n            <button class=\"dist-filter-pill active\" data-filter=\"todos\" data-csp-onclick=\"filterDistribuicao('todos')\">Todos (<span id=\"distCountTodos\">0</span>)</button>\r\n            <button class=\"dist-filter-pill\" data-filter=\"pendentes\" data-csp-onclick=\"filterDistribuicao('pendentes')\">⏳ Na Fila (<span id=\"distCountPend\">0</span>)</button>\r\n            <button class=\"dist-filter-pill\" data-filter=\"conferidos\" data-csp-onclick=\"filterDistribuicao('conferidos')\">✔ Conferidos (<span id=\"distCountConf\">0</span>)</button>\r\n            <button class=\"dist-filter-pill\" data-filter=\"divergentes\" data-csp-onclick=\"filterDistribuicao('divergentes')\">✖ Divergências (<span id=\"distCountDiv\">0</span>)</button>\r\n          </div>\r\n          <span class=\"distribuicao-tip\">📍 Localização de cada palete (ex: <b>SO01A</b>, <b>SO02B</b>)</span>\r\n        </div>\r\n        <div id=\"listDistribuicaoPaletes\" class=\"distribuicao-table-wrap\"></div>\r\n      </div>\r\n\r\n      <!-- TAB 2: Histórico de Bipagens Físicas (Feed cronológico com horários) -->\r\n      <div id=\"tabContentHistorico\" class=\"paletes-tab-content\" style=\"display: none;\">\r\n        <div class=\"timeline-header\" style=\"background: #FAFAFA; border-bottom: 1px solid var(--border-light);\">\r\n          <span>Feed de Leituras do Leitor</span>\r\n          <span id=\"badgeHistCount\" style=\"color: var(--text-muted); font-size: 0.75rem;\">0 paletes</span>\r\n        </div>\r\n        <div id=\"listHistorico\" class=\"timeline-body\">\r\n          <div style=\"text-align: center; color: var(--text-muted); padding: 28px; font-size: 0.88rem;\">\r\n            Nenhum palete bipado ainda. Aponte o leitor para as etiquetas de LPN no Stage.\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- Action Bar Inferior -->\r\n    <footer class=\"action-bar-bottom\">\r\n      <div style=\"display: flex; gap: 8px; align-items: center; flex-wrap: wrap;\">\r\n        <button id=\"btnProximoStage\" type=\"button\" class=\"btn-clean-primary\" style=\"margin: 0; background: #0284C7; border: 1.5px solid #0369A1; font-weight: 800; padding: 10px 18px;\" data-csp-onclick=\"abrirModalProximoStage()\" title=\"Finalizar o stage atual e atrelar um novo stage físico a este embarque\">\r\n          ⏭️ Concluir Stage &amp; Próximo\r\n        </button>\r\n        <button id=\"btnFinalizar\" class=\"btn-finish-clean\">\r\n          ✔ Concluir Embarque\r\n        </button>\r\n        <button id=\"btnCorrigirPaleteModal\" type=\"button\" class=\"btn-secondary-clean\" data-csp-onclick=\"abrirModalCorrecaoLpn()\" title=\"Corrigir ou re-bipar palete/LPN informando o motivo\">\r\n          🔄 Corrigir / Re-bipar LPN\r\n        </button>\r\n        <button id=\"btnExportarRelatorio\" class=\"btn-secondary-clean\">\r\n          Exportar CSV\r\n        </button>\r\n      </div>\r\n      <div style=\"font-size: 0.75rem; font-weight: 600; color: var(--text-muted);\">\r\n        <span class=\"footer-brand-pill\"><span>DHL Supply Chain • Operational Excellence</span><img src=\"data:image/png;base64,\" alt=\"Juntos Imparáveis 2030\" title=\"Juntos Imparáveis 2030\"></span>\r\n      </div>\r\n    </footer>\r\n\r\n  </main>\r\n\r\n  <!-- =========================================================\r\n       TELA 3: DASHBOARD VISUAL DE STAGES (MAPA DO PÁTIO / EXPEDIÇÃO)\r\n       ========================================================= -->\r\n  <main id=\"viewDashboard\" class=\"dashboard-screen\" style=\"display: none;\">\r\n\r\n    <header class=\"dash-header-card\">\r\n      <div class=\"dash-title-row\">\r\n        <div>\r\n          <h1 class=\"dash-main-title\">Mapa de Stages e Pátio de Expedição</h1>\r\n          <p class=\"dash-main-sub\">Gestão visual de alocação de cargas, status e vagas físicas</p>\r\n        </div>\r\n        <div style=\"display: flex; gap: 10px; align-items: center; flex-wrap: wrap;\">\r\n          <!-- Alternador de Visualização -->\r\n          <div class=\"dash-view-toggle\">\r\n            <button id=\"btnModeLayout\" class=\"btn-dash-mode active\" data-csp-onclick=\"StageMap.showLayout('2d')\">Planta 2D</button>\r\n            <button id=\"btnMode3D\" class=\"btn-dash-mode\" data-csp-onclick=\"StageMap.showLayout('3d')\">Visão 3D</button>\r\n            <button id=\"btnModeCards\" class=\"btn-dash-mode\" data-csp-onclick=\"setDashViewMode('cards')\">Cartões</button>\r\n          </div>\r\n          <div class=\"dash-search-wrap\">\r\n            <input type=\"text\" id=\"dashSearchInput\" class=\"dash-search-input\" placeholder=\"Buscar Stage ou Embarque...\" data-csp-oninput=\"handleDashSearch(this.value)\">\r\n          </div>\r\n          <button class=\"btn-secondary-clean\" style=\"margin: 0; padding: 7px 14px;\" data-csp-onclick=\"closeDashboard()\">\r\n            ← Voltar\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- KPIs Globais do Pátio -->\r\n      <div class=\"dash-kpi-bar\" id=\"dashKpiBar\">\r\n        <div class=\"dash-kpi-item\">\r\n          <span class=\"dash-kpi-label\">Stages no Pátio</span>\r\n          <span id=\"dashKpiTotal\" class=\"dash-kpi-val\">67</span>\r\n        </div>\r\n        <div class=\"dash-kpi-item border-free\">\r\n          <span class=\"dash-kpi-label\">Livres</span>\r\n          <span id=\"dashKpiLivre\" class=\"dash-kpi-val text-free\">0</span>\r\n        </div>\r\n        <div class=\"dash-kpi-item border-waiting\">\r\n          <span class=\"dash-kpi-label\">Aguardando</span>\r\n          <span id=\"dashKpiAguardando\" class=\"dash-kpi-val text-waiting\">0</span>\r\n        </div>\r\n        <div class=\"dash-kpi-item border-partial\">\r\n          <span class=\"dash-kpi-label\">Parciais</span>\r\n          <span id=\"dashKpiParcial\" class=\"dash-kpi-val text-partial\">0</span>\r\n        </div>\r\n        <div class=\"dash-kpi-item border-done\">\r\n          <span class=\"dash-kpi-label\">Conferidos</span>\r\n          <span id=\"dashKpiConferido\" class=\"dash-kpi-val text-done\">0</span>\r\n        </div>\r\n        <div class=\"dash-kpi-item border-divergent\">\r\n          <span class=\"dash-kpi-label\">Divergências</span>\r\n          <span id=\"dashKpiDivergente\" class=\"dash-kpi-val text-divergent\">0</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Barra de Filtros -->\r\n      <div class=\"dash-toolbar\" id=\"dashFilterToolbar\">\r\n        <div class=\"dash-filters\">\r\n          <button class=\"dash-filter-btn active\" data-filter=\"all\" data-csp-onclick=\"filterDashboard('all')\">Todos</button>\r\n          <button class=\"dash-filter-btn\" data-filter=\"conferido\" data-csp-onclick=\"filterDashboard('conferido')\">Conferidos</button>\r\n          <button class=\"dash-filter-btn\" data-filter=\"parcial\" data-csp-onclick=\"filterDashboard('parcial')\">Parciais</button>\r\n          <button class=\"dash-filter-btn\" data-filter=\"aguardando\" data-csp-onclick=\"filterDashboard('aguardando')\">Aguardando</button>\r\n          <button class=\"dash-filter-btn\" data-filter=\"livre\" data-csp-onclick=\"filterDashboard('livre')\">Livres</button>\r\n          <button class=\"dash-filter-btn\" data-filter=\"divergencia\" data-csp-onclick=\"filterDashboard('divergencia')\">Com Divergência</button>\r\n        </div>\r\n      </div>\r\n    </header>\r\n\r\n    <!-- Container dos Stages Agrupados por Ruas/Faixas -->\r\n    <section id=\"dashStagesContainer\" class=\"dash-stages-container\"></section>\r\n    <section id=\"stageMapRoot\" class=\"sm-root\" style=\"display:none;\"></section>\r\n\r\n  </main>\r\n\r\n  <!-- =========================================================\r\n       TELA 4: CONSOLIDAÇÃO DE EMBARQUE — SKU+Lote Grouping & Roteirização\r\n       ========================================================= -->\r\n  <main id=\"viewConsolidacao\" class=\"consolidacao-screen\" style=\"display: none;\">\r\n\r\n    <header class=\"cons-header-card\">\r\n      <div class=\"cons-title-row\">\r\n        <div>\r\n          <h1 class=\"cons-main-title\">🔗 Consolidação de Embarque</h1>\r\n          <p class=\"cons-main-sub\">Agrupa paletes por SKU + Lote · Otimiza cubagem · Gera roteirização de stages</p>\r\n          <div style=\"display: inline-flex; align-items: center; gap: 6px; background: #ECFDF5; border: 1px solid #A7F3D0; color: #065F46; font-size: 0.72rem; font-weight: 800; padding: 2px 8px; border-radius: 4px; margin-top: 4px;\">\r\n            🏷️ ATIVIDADE EXTERNA À CONFERÊNCIA • Roteirização & Localidade de Paletes\r\n          </div>\r\n        </div>\r\n        <div style=\"display: flex; gap: 8px; align-items: center; flex-wrap: wrap;\">\r\n          <div style=\"display: flex; align-items: center; gap: 6px; background: #F1F5F9; border: 1px solid var(--border-light); padding: 5px 12px; border-radius: 6px;\">\r\n            <span style=\"font-size: 0.75rem; font-weight: 800; color: var(--text-secondary);\">Embarque:</span>\r\n            <select id=\"consSelectEmbarque\" style=\"background: transparent; border: none; font-weight: 800; font-size: 0.85rem; color: var(--text-primary); outline: none; cursor: pointer;\" data-csp-onchange=\"selecionarEmbarqueConsolidacao(this.value)\">\r\n              <option value=\"\">Carregando...</option>\r\n            </select>\r\n          </div>\r\n          <button class=\"btn-clean-primary\" style=\"margin-top:0;width:auto;padding:8px 16px;\" data-csp-onclick=\"reprocessarConsolidacao()\">\r\n            🔄 Recalcular\r\n          </button>\r\n          <button class=\"btn-secondary-clean\" data-csp-onclick=\"fecharConsolidacaoTela()\">\r\n            ← Voltar à Conferência\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- KPIs de Consolidação -->\r\n      <div class=\"cons-kpi-bar\">\r\n        <div class=\"cons-kpi-item\">\r\n          <span class=\"cons-kpi-label\">Total de Paletes</span>\r\n          <span id=\"consKpiTotal\" class=\"cons-kpi-val\">0</span>\r\n        </div>\r\n        <div class=\"cons-kpi-item cons-kpi-alert\">\r\n          <span class=\"cons-kpi-label\">SKU+Lote Duplicados</span>\r\n          <span id=\"consKpiDuplicados\" class=\"cons-kpi-val\" style=\"color:#DC2626;\">0</span>\r\n        </div>\r\n        <div class=\"cons-kpi-item cons-kpi-ok\">\r\n          <span class=\"cons-kpi-label\">Paletes Consolidáveis</span>\r\n          <span id=\"consKpiConsolidaveis\" class=\"cons-kpi-val\" style=\"color:#FF7A00;\">0</span>\r\n        </div>\r\n        <div class=\"cons-kpi-item cons-kpi-gain\">\r\n          <span class=\"cons-kpi-label\">Economia de Espaço</span>\r\n          <span id=\"consKpiEconomia\" class=\"cons-kpi-val\" style=\"color:#00A650;\">0 paletes</span>\r\n        </div>\r\n        <div class=\"cons-kpi-item\">\r\n          <span class=\"cons-kpi-label\">Embarque</span>\r\n          <span id=\"consKpiEmbarque\" class=\"cons-kpi-val\" style=\"font-size:1rem;\">—</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Filtro Rápido -->\r\n      <div class=\"cons-toolbar\">\r\n        <div class=\"cons-filters\">\r\n          <button class=\"cons-filter-btn active\" data-filter=\"todos\" data-csp-onclick=\"filtrarConsolidacao('todos')\">Todos os Grupos</button>\r\n          <button class=\"cons-filter-btn\" data-filter=\"duplicado\" data-csp-onclick=\"filtrarConsolidacao('duplicado')\">⚠️ Duplicados (Consolidar)</button>\r\n          <button class=\"cons-filter-btn\" data-filter=\"unico\" data-csp-onclick=\"filtrarConsolidacao('unico')\">✔ Únicos (Sem Ação)</button>\r\n        </div>\r\n        <input type=\"text\" id=\"consSearchInput\" class=\"cons-search-input\" placeholder=\"Filtrar por SKU, Lote ou Descrição...\" data-csp-oninput=\"filtrarConsolidacaoTexto(this.value)\">\r\n      </div>\r\n    </header>\r\n\r\n    <!-- Mapa 2D/3D da consolidação: origem → destino (roteirização) -->\r\n    <section id=\"consMapRoot\" class=\"sm-root\" style=\"margin: 0 0 16px;\"></section>\r\n\r\n    <!-- Roteirização Global -->\r\n    <section id=\"consRoteirizacaoGlobal\" class=\"cons-roteirizacao-global\" style=\"display:none;\">\r\n      <div class=\"cons-route-title\">\r\n        <span>📐 Roteirização & Ordem da Rota de Stages (A, B, C...)</span>\r\n        <button class=\"cons-route-toggle\" data-csp-onclick=\"toggleRoteirizacaoGlobal()\">▼ Ver / Ocultar</button>\r\n      </div>\r\n      <div id=\"consRoteirizacaoBody\" class=\"cons-route-body\"></div>\r\n    </section>\r\n\r\n    <!-- Grid de Grupos -->\r\n    <section id=\"consGruposContainer\" class=\"cons-grupos-container\"></section>\r\n\r\n  </main>\r\n\r\n  <!-- =========================================================\r\n       TELA 5: DASHBOARD ANALÍTICO DE OPERAÇÕES & OPORTUNIDADES\r\n       ========================================================= -->\r\n  <main id=\"viewAnalyticsDashboard\" class=\"main-wrapper\" style=\"display: none; padding-bottom: 60px;\">\r\n    <div id=\"analyticsDashboardRoot\"></div>\r\n  </main>\r\n\r\n  <!-- =========================================================\r\n       MODAL 0: DETALHES E INSPEÇÃO DE VAGAS DO STAGE\r\n       ========================================================= -->\r\n  <div id=\"modalStageDetail\" class=\"modal-backdrop\" style=\"display: none;\">\r\n    <div class=\"modal-clean-box modal-lg\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; border-bottom: 1px solid var(--border-light); padding-bottom: 10px;\">\r\n        <div>\r\n          <h2 id=\"stageDetailTitle\" style=\"font-size: 1.15rem; font-weight: 800; color: var(--text-primary); margin: 0;\">Stage</h2>\r\n          <span id=\"stageDetailSub\" style=\"font-size: 0.78rem; color: var(--text-muted);\">Alocação e detalhamento físico de posições</span>\r\n        </div>\r\n        <button id=\"btnCloseModalStageDetail\" class=\"btn-close-x\" data-csp-onclick=\"closeStageDetailModal()\">&times;</button>\r\n      </div>\r\n\r\n      <div id=\"stageDetailBody\"></div>\r\n\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 18px; border-top: 1px solid var(--border-light); padding-top: 12px; flex-wrap: wrap; gap: 8px;\">\r\n        <div id=\"stageDetailFooterInfo\" style=\"font-size: 0.8rem; color: var(--text-muted);\"></div>\r\n        <div style=\"display: flex; gap: 8px; flex-wrap: wrap;\">\r\n          <button id=\"btnVerNoPatioGeral\" class=\"btn-secondary-clean\" style=\"color: #0284C7; border-color: #BAE6FD; font-weight: 800; background: #F0F9FF;\">\r\n            🗺️ Ver no Mapa do Pátio\r\n          </button>\r\n          <button id=\"btnConferirStageAgora\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 18px;\">\r\n            Abrir Conferência Deste Stage\r\n          </button>\r\n          <button class=\"btn-secondary-clean\" data-csp-onclick=\"closeStageDetailModal()\">Fechar</button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 0B: AUDITORIA AMOSTRAL 10% (QUANTIDADE E LOTE)\r\n       ========================================================= -->\r\n  <div id=\"modalAmostragemQtdLote\" class=\"modal-backdrop\" style=\"display: none;\">\r\n    <div class=\"modal-clean-box\" style=\"max-width: 480px; border-top: 4px solid #FFCC00;\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; border-bottom: 1.5px solid #F1F5F9; padding-bottom: 10px;\">\r\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\r\n          <span style=\"font-size: 1.5rem;\">🎲</span>\r\n          <div>\r\n            <h2 style=\"font-size: 1.1rem; font-weight: 800; color: #1E293B; margin: 0;\">Auditoria Amostral 10% DHL</h2>\r\n            <span style=\"font-size: 0.76rem; color: #64748B;\">Conferência física aleatória de Caixas e Lote</span>\r\n          </div>\r\n        </div>\r\n        <button type=\"button\" class=\"btn-close-x\" data-csp-onclick=\"cancelarAmostraAudit()\">&times;</button>\r\n      </div>\r\n\r\n      <div id=\"amostraAuditPalletInfo\" style=\"background: #F8FAFC; border: 1px solid #E2E8F0; border-radius: 8px; padding: 12px; margin-bottom: 12px;\"></div>\r\n\r\n      <div id=\"amostraTentativasBadge\" style=\"display: flex; align-items: center; justify-content: space-between; background: #EFF6FF; border: 1px solid #BFDBFE; border-radius: 6px; padding: 6px 12px; margin-bottom: 12px; font-size: 0.8rem; font-weight: 700; color: #1E40AF;\">\r\n        <span>🎯 Tentativa <span id=\"amostraNumTentativa\" style=\"background:#2563EB; color:#fff; padding:2px 7px; border-radius:12px; font-weight:800;\">1</span> de 3</span>\r\n        <span id=\"amostraTentativasDica\" style=\"font-weight: 600; font-size: 0.74rem; color: #3B82F6;\">Até 3 chances antes de acionar Inventário</span>\r\n      </div>\r\n\r\n      <div id=\"amostraErroFeedback\" style=\"display: none; background: #FEF2F2; border: 1.5px solid #F87171; border-radius: 8px; padding: 10px; margin-bottom: 14px; font-size: 0.82rem; color: #991B1B; line-height: 1.4;\"></div>\r\n\r\n      <form id=\"formAmostraAudit\" data-csp-onsubmit=\"confirmarAmostraAudit(event)\">\r\n        <div class=\"form-field\" style=\"margin-bottom: 14px;\">\r\n          <label for=\"auditInputQtd\" style=\"font-weight: 700; color: #1E293B; font-size: 0.85rem;\">\r\n            📦 Quantidade de Caixas / Volumes Contados:\r\n          </label>\r\n          <input type=\"number\" id=\"auditInputQtd\" class=\"input-clean\" required min=\"1\" placeholder=\"Informe a contagem física...\" style=\"font-size: 1.1rem; font-weight: 800; color: #0284C7;\">\r\n        </div>\r\n\r\n        <div class=\"form-field\" style=\"margin-bottom: 18px;\">\r\n          <label for=\"auditInputLote\" style=\"font-weight: 700; color: #1E293B; font-size: 0.85rem;\">\r\n            🏷️ Lote Físico no Palete / Caixa:\r\n          </label>\r\n          <input type=\"text\" id=\"auditInputLote\" class=\"input-clean\" required placeholder=\"Digite o Lote físico...\" style=\"font-size: 1.1rem; font-weight: 800; color: #0284C7;\" autocomplete=\"off\" spellcheck=\"false\">\r\n        </div>\r\n\r\n        <div style=\"display: flex; gap: 10px; justify-content: flex-end;\">\r\n          <button type=\"button\" class=\"btn-secondary-clean\" data-csp-onclick=\"cancelarAmostraAudit()\">Cancelar</button>\r\n          <button type=\"submit\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 10px 22px; font-weight: 800;\">\r\n            ✔ Confirmar Palete [ENTER]\r\n          </button>\r\n        </div>\r\n      </form>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 0B2: CONCLUIR STAGE ATUAL & ATRELAR PRÓXIMO STAGE\r\n       ========================================================= -->\r\n  <div id=\"modalProximoStage\" class=\"modal-backdrop\" style=\"display: none;\">\r\n    <div class=\"modal-clean-box\" style=\"max-width: 500px; border-top: 4px solid #0284C7;\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; border-bottom: 1.5px solid #F1F5F9; padding-bottom: 10px;\">\r\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\r\n          <span style=\"font-size: 1.5rem;\">⏭️</span>\r\n          <div>\r\n            <h2 style=\"font-size: 1.15rem; font-weight: 800; color: #1E293B; margin: 0;\">Concluir Stage &amp; Atrelar Próximo</h2>\r\n            <span style=\"font-size: 0.76rem; color: #64748B;\">Atrelamento de novo stage físico ao mesmo embarque</span>\r\n          </div>\r\n        </div>\r\n        <button type=\"button\" class=\"btn-close-x\" data-csp-onclick=\"fecharModalProximoStage()\">&times;</button>\r\n      </div>\r\n\r\n      <div style=\"background: #F0F9FF; border: 1px solid #BAE6FD; border-radius: 8px; padding: 12px; margin-bottom: 16px; font-size: 0.85rem; color: #0369A1; line-height: 1.5;\">\r\n        <div><b>Stage Físico Atual:</b> <span id=\"proxStageAtualNome\" style=\"font-weight: 900; color: #0284C7;\">SO011</span> (Concluído)</div>\r\n        <div style=\"font-size: 0.78rem; color: #0C4A6E; margin-top: 4px;\">\r\n          As vagas deste stage foram finalizadas. Para continuar o embarque, informe o código do próximo stage que receberá os paletes.\r\n        </div>\r\n      </div>\r\n\r\n      <form id=\"formProximoStage\" data-csp-onsubmit=\"confirmarProximoStage(event)\">\r\n        <div class=\"form-field\" style=\"margin-bottom: 18px;\">\r\n          <label for=\"inputProximoStageCode\" style=\"font-weight: 700; color: #1E293B; font-size: 0.88rem; display: block; margin-bottom: 6px;\">\r\n            🏷️ Bipe ou digite o código do PRÓXIMO STAGE:\r\n          </label>\r\n          <input type=\"text\" id=\"inputProximoStageCode\" class=\"input-clean\" required placeholder=\"Bipe aqui (ex: SO012, SO013, ST040)...\" style=\"font-size: 1.15rem; font-weight: 800; color: #0284C7; text-transform: uppercase;\" autocomplete=\"off\" spellcheck=\"false\">\r\n          <small style=\"color: #64748B; font-size: 0.75rem; margin-top: 4px; display: block;\">\r\n            Você pode bipar a placa física do stage diretamente com o leitor de código de barras.\r\n          </small>\r\n        </div>\r\n\r\n        <div style=\"display: flex; gap: 10px; justify-content: flex-end;\">\r\n          <button type=\"button\" class=\"btn-secondary-clean\" data-csp-onclick=\"fecharModalProximoStage()\">Cancelar</button>\r\n          <button type=\"submit\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 10px 22px; font-weight: 800; background: #0284C7;\">\r\n            ✔ Atrelar e Abrir Novo Stage [ENTER]\r\n          </button>\r\n        </div>\r\n      </form>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 0B3: CORREÇÃO & RE-BIPAGEM DE LPN COM SELEÇÃO DE MOTIVO\r\n       ========================================================= -->\r\n  <div id=\"modalCorrecaoLpn\" class=\"modal-backdrop\" style=\"display: none;\">\r\n    <div class=\"modal-clean-box\" style=\"max-width: 520px; border-top: 4px solid #D97706;\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; border-bottom: 1.5px solid #F1F5F9; padding-bottom: 10px;\">\r\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\r\n          <span style=\"font-size: 1.5rem;\">🔄</span>\r\n          <div>\r\n            <h2 style=\"font-size: 1.15rem; font-weight: 800; color: #1E293B; margin: 0;\">Correção &amp; Re-bipagem de LPN</h2>\r\n            <span style=\"font-size: 0.76rem; color: #64748B;\">Selecione a vaga, a LPN e o motivo para re-bipar</span>\r\n          </div>\r\n        </div>\r\n        <button type=\"button\" class=\"btn-close-x\" data-csp-onclick=\"fecharModalCorrecaoLpn()\">&times;</button>\r\n      </div>\r\n\r\n      <form id=\"formCorrecaoLpn\" data-csp-onsubmit=\"confirmarRebipagemLpn(event)\">\r\n        <!-- 1. Vaga a Corrigir -->\r\n        <div class=\"form-field\" style=\"margin-bottom: 14px;\">\r\n          <label for=\"selectVagaCorrecao\" style=\"font-weight: 700; color: #1E293B; font-size: 0.85rem; display: block; margin-bottom: 4px;\">\r\n            📍 Selecione a Vaga que precisa ser corrigida:\r\n          </label>\r\n          <select id=\"selectVagaCorrecao\" class=\"input-clean\" style=\"font-weight: 800; color: #0284C7; font-size: 0.95rem;\" data-csp-onchange=\"aoMudarVagaCorrecao(this.value)\">\r\n            <option value=\"\">Carregando vagas conferidas...</option>\r\n          </select>\r\n        </div>\r\n\r\n        <!-- 2. Paletes / LPNs presentes nesta vaga (suporte a duplado/fracionado) -->\r\n        <div id=\"boxLpnsNaVaga\" style=\"background: #F8FAFC; border: 1px solid #E2E8F0; border-radius: 8px; padding: 12px; margin-bottom: 14px;\">\r\n          <div style=\"font-size: 0.78rem; font-weight: 800; color: #475569; text-transform: uppercase; margin-bottom: 6px;\">\r\n            📦 LPN(s) nesta Vaga (Selecione qual deseja re-bipar):\r\n          </div>\r\n          <div id=\"listaLpnsVagaRadio\" style=\"display: flex; flex-direction: column; gap: 6px; font-size: 0.85rem;\"></div>\r\n        </div>\r\n\r\n        <!-- 3. Motivo da Re-bipagem (Select Point / Checkbox) -->\r\n        <div class=\"form-field\" style=\"margin-bottom: 16px;\">\r\n          <label style=\"font-weight: 800; color: #1E293B; font-size: 0.85rem; display: block; margin-bottom: 8px;\">\r\n            ⚠️ Motivo da Correção / Re-bipagem:\r\n          </label>\r\n          <div style=\"display: flex; flex-direction: column; gap: 8px; font-size: 0.84rem; color: #1E293B; background: #FFFBEB; border: 1px solid #FDE68A; padding: 12px; border-radius: 8px;\">\r\n            <label style=\"display: flex; align-items: center; gap: 8px; cursor: pointer;\">\r\n              <input type=\"radio\" name=\"motivoRebipagem\" value=\"LPN_INCORRETA\" checked>\r\n              <span><b>Bipagem de LPN incorreta</b> (LPN trocada ou leitor capturou código errado)</span>\r\n            </label>\r\n            <label style=\"display: flex; align-items: center; gap: 8px; cursor: pointer;\">\r\n              <input type=\"radio\" name=\"motivoRebipagem\" value=\"PALETE_DIVERGENTE\">\r\n              <span><b>Palete físico divergente</b> (Palete não pertence a este stage/vaga)</span>\r\n            </label>\r\n            <label style=\"display: flex; align-items: center; gap: 8px; cursor: pointer;\">\r\n              <input type=\"radio\" name=\"motivoRebipagem\" value=\"TROCA_POSICAO\">\r\n              <span><b>Inversão de posição</b> (Reordenar vaga física no stage)</span>\r\n            </label>\r\n            <label style=\"display: flex; align-items: center; gap: 8px; cursor: pointer;\">\r\n              <input type=\"radio\" name=\"motivoRebipagem\" value=\"AJUSTE_DUPLADO_FRACIONADO\">\r\n              <span><b>Ajuste de Duplado / Fracionado</b> (Remover nível incorreto)</span>\r\n            </label>\r\n            <label style=\"display: flex; align-items: center; gap: 8px; cursor: pointer;\">\r\n              <input type=\"radio\" name=\"motivoRebipagem\" value=\"RECONTAGEM_QUALIDADE\">\r\n              <span><b>Recontagem / Auditoria</b> (Solicitação do Inventário ou Liderança)</span>\r\n            </label>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- 4. Observação Opcional -->\r\n        <div class=\"form-field\" style=\"margin-bottom: 18px;\">\r\n          <label for=\"inputObsCorrecao\" style=\"font-weight: 700; color: #475569; font-size: 0.78rem;\">\r\n            Observação complementar (opcional):\r\n          </label>\r\n          <input type=\"text\" id=\"inputObsCorrecao\" class=\"input-clean\" placeholder=\"Ex: Substituído pelo palete correto da doca...\">\r\n        </div>\r\n\r\n        <div style=\"display: flex; gap: 10px; justify-content: flex-end;\">\r\n          <button type=\"button\" class=\"btn-secondary-clean\" data-csp-onclick=\"fecharModalCorrecaoLpn()\">Cancelar</button>\r\n          <button type=\"submit\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 10px 22px; font-weight: 800; background: #D97706;\">\r\n            🔄 Liberar Vaga &amp; Re-bipar Agora\r\n          </button>\r\n        </div>\r\n      </form>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 0C: BLOQUEIO OBRIGATÓRIO DE STAGE LOTADO\r\n       ========================================================= -->\r\n  <div id=\"modalStageLotado\" class=\"modal-backdrop\" style=\"display: none;\">\r\n    <div class=\"modal-clean-box\" style=\"max-width: 500px; border-top: 5px solid #DC2626;\">\r\n      <div style=\"text-align: center; margin-bottom: 14px;\">\r\n        <span style=\"font-size: 3rem; display: block; margin-bottom: 8px;\">🛑</span>\r\n        <h2 style=\"font-size: 1.25rem; font-weight: 900; color: #DC2626; margin: 0 0 6px;\">\r\n          STAGE LOTADO (10/10 VAGAS)\r\n        </h2>\r\n        <span id=\"stageLotadoMsg\" style=\"font-size: 0.9rem; color: #475569; font-weight: 600;\">\r\n          O Stage atingiu a capacidade máxima física de 10 vagas.\r\n        </span>\r\n      </div>\r\n\r\n      <div style=\"background: #FEF2F2; border: 1.5px dashed #EF4444; border-radius: 8px; padding: 14px; margin-bottom: 18px; text-align: center;\">\r\n        <div style=\"font-size: 0.88rem; font-weight: 800; color: #991B1B; margin-bottom: 6px;\">\r\n          AÇÃO OBRIGATÓRIA DA OPERAÇÃO:\r\n        </div>\r\n        <div style=\"font-size: 0.92rem; color: #1E293B; line-height: 1.4;\">\r\n          Bipe a placa do próximo Stage físico (<b>ST...</b> ou <b>SO...</b>) onde os próximos paletes serão posicionados.\r\n        </div>\r\n        <div style=\"margin-top: 12px; display: flex; gap: 8px;\">\r\n          <input type=\"text\" id=\"inputScanNewStage\" class=\"scan-input-ultra\" \r\n                 placeholder=\"Bipe ST ou SO aqui com o leitor...\" \r\n                 style=\"font-size: 1rem; padding: 10px 14px; text-align: center; border-color: #DC2626; background: #fff; flex: 1;\" \r\n                 autocomplete=\"off\" spellcheck=\"false\" data-csp-onkeydown=\"handleNewStageInputKey(event)\">\r\n          <button type=\"button\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 10px 18px; background: #DC2626;\" data-csp-onclick=\"confirmarNovoStageManual()\">\r\n            Ativar Stage\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center;\">\r\n        <span style=\"font-size: 0.78rem; color: #94A3B8;\">Nenhum palete adicional pode ser bipado no stage cheio.</span>\r\n        <button type=\"button\" class=\"btn-secondary-clean\" data-csp-onclick=\"fecharModalStageLotado()\">Fechar</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 1: ATUALIZAR BASE / UPLOAD EXCEL (.XLSX)\r\n       ========================================================= -->\r\n  <div id=\"modalUpload\" class=\"modal-backdrop\">\r\n    <div class=\"modal-clean-box modal-lg\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; border-bottom: 1px solid var(--border-light); padding-bottom: 12px;\">\r\n        <div>\r\n          <h2 style=\"font-size: 1.15rem; font-weight: 800; color: var(--text-primary);\">Atualizar Base com Planilha Excel</h2>\r\n          <span style=\"font-size: 0.78rem; color: var(--text-muted);\">Importe guias de conferência ou relatórios do WMS diretamente pelo navegador</span>\r\n        </div>\r\n        <button id=\"btnCloseModalUpload\" class=\"btn-close-x\">&times;</button>\r\n      </div>\r\n\r\n      <!-- Alerta de Segurança do Histórico -->\r\n      <div class=\"safe-history-notice\">\r\n        <span style=\"font-size: 1.2rem;\">🔒</span>\r\n        <div>\r\n          <b>Histórico 100% Protegido:</b> Suas conferências anteriores, bipagens já realizadas e auditorias salvas NÃO serão perdidas ao atualizar a base. Novos embarques são somados e atualizados com segurança.\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Drag & Drop Zone -->\r\n      <div id=\"dropZone\" class=\"upload-dropzone\">\r\n        <div class=\"dropzone-icon\">📥</div>\r\n        <div class=\"dropzone-title\">Arraste e solte o arquivo Excel (.xlsx) ou CSV aqui</div>\r\n        <div class=\"dropzone-subtitle\">Suporta <b>data - 2026-*.xlsx</b>, <b>data (1).xlsx</b>, <b>ADHOC_80.xlsx</b> ou <b>ADHOC_80.csv</b><br><span style=\"font-size:0.74rem; color:#B45309;\">💡 No Power BI, exporte com <b>\"Dados com layout atual\"</b> ou <b>\".xlsx (Excel 150.000 linhas)\"</b> (não use \"Tabela com conexão dinâmica\")</span></div>\r\n        \r\n        <label for=\"excelFileInput\" class=\"btn-file-select\">\r\n          Selecionar Arquivo (.xlsx / .csv)\r\n        </label>\r\n        <input type=\"file\" id=\"excelFileInput\" accept=\".xlsx, .xls, .csv\" style=\"display: none;\">\r\n      </div>\r\n\r\n      <!-- Feedback de Processamento do Upload -->\r\n      <div id=\"uploadFeedback\" style=\"display: none; margin-top: 16px;\"></div>\r\n\r\n      <!-- Opção Direta via API: Extrair XLSX/CSV do SharePoint / Downloads -->\r\n      <div style=\"background: #FEF3C7; border: 1px solid #FCD34D; border-radius: 8px; padding: 14px; margin-top: 16px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px;\">\r\n        <div>\r\n          <div style=\"font-size: 0.88rem; font-weight: 800; color: #92400E; display: flex; align-items: center; gap: 6px;\">\r\n            <span>📁</span> Carregar Base Oficial Integrada (272 Embarques • 9.021 Paletes)\r\n          </div>\r\n          <div style=\"font-size: 0.76rem; color: #B45309; margin-top: 2px;\">\r\n            Aplica a base real sincronizada ou busca atualizações recentes no SharePoint / Downloads\r\n          </div>\r\n        </div>\r\n        <button type=\"button\" class=\"btn-clean-primary\" id=\"btnExtrairSharePointApi\" style=\"margin-top: 0; width: auto; padding: 9px 18px; background: #D97706; font-weight: 700;\" data-csp-onclick=\"extrairCsvSharePoint()\">\r\n          ⚡ Carregar Base Real\r\n        </button>\r\n      </div>\r\n\r\n      <!-- Opção 100% no Navegador: Colar Texto do CSV Diretamente -->\r\n      <details style=\"margin-top: 14px; background: #F8FAFC; border: 1px solid #E2E8F0; border-radius: 8px; padding: 12px;\">\r\n        <summary style=\"font-size: 0.84rem; font-weight: 700; color: #334155; cursor: pointer; display: flex; align-items: center; gap: 6px;\">\r\n          <span>📋</span> Ou cole os dados do CSV diretamente aqui (100% no HTML)\r\n        </summary>\r\n        <div style=\"margin-top: 10px;\">\r\n          <textarea id=\"txtCsvManual\" rows=\"4\" style=\"width: 100%; box-sizing: border-box; font-family: Consolas, monospace; font-size: 0.76rem; border: 1px solid #CBD5E1; border-radius: 6px; padding: 8px;\" placeholder=\"Cole aqui o conteúdo do CSV (ex: [car_move_id],[ORDNUM],[PALLET_ID],[DSTLOC],[PRTNUM],[QTD_CAIXAS]...)\"></textarea>\r\n          <button type=\"button\" class=\"btn-clean-primary\" style=\"margin-top: 8px; width: 100%; padding: 8px; font-size: 0.82rem; background: #0284C7;\" data-csp-onclick=\"processarTextoCsvColado()\">\r\n            📥 Injetar CSV na Ferramenta Agora\r\n          </button>\r\n        </div>\r\n      </details>\r\n\r\n      <!-- Opção Power BI Relatório Oficial Web (Link Direto & Embed) -->\r\n      <div style=\"background: #EFF6FF; border: 1.5px solid #3B82F6; border-radius: 8px; padding: 14px; margin-top: 16px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px;\">\r\n        <div style=\"flex: 1; min-width: 260px;\">\r\n          <div style=\"font-size: 0.9rem; font-weight: 800; color: #1E40AF; display: flex; align-items: center; gap: 6px;\">\r\n            <span>📊</span> Relatório Oficial AD HOC 80 (Power BI Web)\r\n          </div>\r\n          <div style=\"font-size: 0.77rem; color: #1D4ED8; margin-top: 3px; line-height: 1.4;\">\r\n            Abra diretamente para exportar os dados atualizados (<b>\"...\" &gt; Exportar dados &gt; Excel .xlsx</b>) ou visualize na ferramenta:\r\n          </div>\r\n        </div>\r\n        <div style=\"display: flex; gap: 8px; flex-wrap: wrap;\">\r\n          <button type=\"button\" class=\"btn-secondary-clean\" style=\"margin: 0; background: #FFF; color: #003DA5; border-color: #93C5FD; font-weight: 700;\" data-csp-onclick=\"abrirModalPowerBiIframe()\">\r\n            🖥️ Abrir Aqui\r\n          </button>\r\n          <a href=\"https://app.powerbi.com/groups/me/reports/3cf5dcbd-f996-4d3e-afd5-564fbf1a6761/9d415a94aa4fce655114?ctid=3596192b-fdf5-4e2c-a6fa-acb706c963d8&amp;experience=power-bi\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 16px; background: #003DA5; text-decoration: none; display: inline-flex; align-items: center; gap: 6px; font-weight: 800;\">\r\n            🔗 Abrir no Power BI ↗\r\n          </a>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Opção Rápida via Power BI Live API (Code) -->\r\n      <div style=\"background: #F8FAFC; border: 1px solid #E2E8F0; border-radius: 8px; padding: 12px; margin-top: 12px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 10px;\">\r\n        <div>\r\n          <div style=\"font-size: 0.85rem; font-weight: 800; color: #334155;\">⚡ Power BI Live API (DAX On-Time)</div>\r\n          <div style=\"font-size: 0.75rem; color: #64748B;\">Consulta direta via DAX sem arquivos intermediários (100% Code)</div>\r\n        </div>\r\n        <button type=\"button\" class=\"btn-secondary-clean\" style=\"margin-top: 0; width: auto; padding: 8px 16px; font-weight: 700;\" data-csp-onclick=\"openPowerBiModal()\">\r\n          ⚡ Configurar API Live\r\n        </button>\r\n      </div>\r\n\r\n\r\n\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 16px; border-top: 1px solid var(--border-light); padding-top: 14px;\">\r\n        <div style=\"font-size: 0.8rem; color: var(--text-muted);\">\r\n          ⚡ Sincronização On-Time ativa: Qualquer alteração ou nova carga é transmitida automaticamente para todos os aparelhos conectados.\r\n        </div>\r\n        <div style=\"display: flex; gap: 8px;\">\r\n          <button id=\"btnResetBaseDefault\" class=\"btn-secondary-clean\" data-csp-onclick=\"limparBaseCustomizada()\" style=\"margin-left: 0; color: #b91c1c; border-color: #fca5a5;\">Restaurar Padrão</button>\r\n          <button id=\"btnFecharUpload\" class=\"btn-secondary-clean\" style=\"margin-left: 0;\" data-csp-onclick=\"document.getElementById('modalUpload').style.display='none'\">Fechar</button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL: HISTÓRICO COMPLETO DA FERRAMENTA (ABAS UNIFICADAS)\r\n       ========================================================= -->\r\n  <div id=\"modalHistorico\" class=\"modal-backdrop\">\r\n    <div class=\"modal-clean-box modal-lg\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; border-bottom: 1px solid var(--border-light); padding-bottom: 10px;\">\r\n        <div>\r\n          <h2 style=\"font-size: 1.15rem; font-weight: 800; color: var(--text-primary); margin: 0;\">Histórico da Ferramenta</h2>\r\n          <span style=\"font-size: 0.78rem; color: var(--text-muted);\">Auditorias, ocorrências de inventário e evolução de carga</span>\r\n        </div>\r\n        <button id=\"btnCloseModalHist\" class=\"btn-close-x\">&times;</button>\r\n      </div>\r\n\r\n      <!-- Abas Internas -->\r\n      <div class=\"hist-tabs-bar\">\r\n        <button class=\"hist-tab-btn active\" id=\"tabBtnConf\" data-csp-onclick=\"switchHistTab('conf')\">\r\n          📦 Conferências (<span id=\"tabBadgeConf\">0</span>)\r\n        </button>\r\n        <button class=\"hist-tab-btn\" id=\"tabBtnOcorr\" data-csp-onclick=\"switchHistTab('ocorr')\">\r\n          🚨 Ocorrências / Inventário (<span id=\"tabBadgeOcorr\">0</span>)\r\n        </button>\r\n        <button class=\"hist-tab-btn\" id=\"tabBtnEvol\" data-csp-onclick=\"switchHistTab('evol')\">\r\n          📈 Evolução da Base (<span id=\"tabBadgeEvol\">0</span>)\r\n        </button>\r\n      </div>\r\n\r\n      <!-- ABA 1: CONFERÊNCIAS DE STAGE -->\r\n      <div id=\"paneConf\" class=\"hist-tab-pane active\">\r\n        <!-- KPIs do Histórico -->\r\n        <div class=\"hist-kpi-bar\">\r\n          <div class=\"hist-kpi-item\">\r\n            <span class=\"kpi-label\">Auditorias Salvas</span>\r\n            <span id=\"histTotalCount\" class=\"kpi-val\">0</span>\r\n          </div>\r\n          <div class=\"hist-kpi-item\">\r\n            <span class=\"kpi-label\">Paletes Auditados</span>\r\n            <span id=\"histTotalPaletes\" class=\"kpi-val green\">0</span>\r\n          </div>\r\n          <div class=\"hist-kpi-item\">\r\n            <span class=\"kpi-label\">Divergências Detectadas</span>\r\n            <span id=\"histTotalDivergencias\" class=\"kpi-val red\">0</span>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"hist-table-wrap\">\r\n          <table class=\"clean-data-table\">\r\n            <thead>\r\n              <tr>\r\n                <th>Data/Hora</th>\r\n                <th>Embarque</th>\r\n                <th>Operador</th>\r\n                <th>Stage</th>\r\n                <th>Progresso</th>\r\n                <th>Divergências</th>\r\n                <th>Status</th>\r\n                <th>Ações</th>\r\n              </tr>\r\n            </thead>\r\n            <tbody id=\"histTableBody\"></tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 16px; border-top: 1px solid var(--border-light); padding-top: 12px;\">\r\n          <div style=\"display: flex; gap: 8px; flex-wrap: wrap;\">\r\n            <button id=\"btnExportarTodoHistorico\" class=\"btn-secondary-clean\" style=\"margin-left: 0;\">\r\n              📥 Exportar Conferências (CSV)\r\n            </button>\r\n            <button id=\"btnExportarBancoCompletoExcel\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 7px 14px; background: #047857; font-size: 0.8rem; font-weight: 700;\" data-csp-onclick=\"window.DHL_DB && window.DHL_DB.exportarBancoExcel()\" title=\"Exporta todas as tabelas do IndexedDB (Conferências, Bipagens com Vaga, Ocorrências e Base) para uma planilha Excel\">\r\n              📊 Baixar Banco Completo (.xlsx)\r\n            </button>\r\n          </div>\r\n          <button id=\"btnFecharModalHist\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 20px;\">\r\n            Fechar\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- ABA 2: OCORRÊNCIAS DE INVENTÁRIO (PALETES DE OUTROS EMBARQUES) -->\r\n      <div id=\"paneOcorr\" class=\"hist-tab-pane\">\r\n        <div style=\"font-size: 0.82rem; color: var(--text-secondary); margin-bottom: 10px;\">\r\n          Paletes bipados que não pertenciam ao embarque auditado. Use para acionar e corrigir no inventário:\r\n        </div>\r\n        <div class=\"hist-table-wrap\">\r\n          <table class=\"clean-data-table\">\r\n            <thead>\r\n              <tr>\r\n                <th>Data/Hora</th>\r\n                <th>LPN Bipada</th>\r\n                <th>Stage Físico</th>\r\n                <th>Embarque Bipado</th>\r\n                <th>Embarque Correto (WMS)</th>\r\n                <th>Stage Correto</th>\r\n                <th>Material / SKU</th>\r\n                <th>Ação</th>\r\n              </tr>\r\n            </thead>\r\n            <tbody id=\"tableOcorrenciasBody\"></tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 16px; border-top: 1px solid var(--border-light); padding-top: 12px;\">\r\n          <button id=\"btnExportarOcorrenciasCSV\" class=\"btn-secondary-clean\" style=\"margin-left: 0;\">\r\n            📥 Exportar Ocorrências para Inventário (CSV)\r\n          </button>\r\n          <button class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 20px;\" data-csp-onclick=\"document.getElementById('modalHistorico').style.display='none'\">\r\n            Fechar\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- ABA 3: EVOLUÇÃO DA BASE (VERSIONAMENTO) -->\r\n      <div id=\"paneEvol\" class=\"hist-tab-pane\">\r\n        <div style=\"font-size: 0.82rem; color: var(--text-secondary); margin-bottom: 10px;\">\r\n          Histórico de evolução e atualização da base. Permite acompanhar paletes adicionados ou excluídos pelo WMS:\r\n        </div>\r\n        <div class=\"hist-table-wrap\">\r\n          <table class=\"clean-data-table\">\r\n            <thead>\r\n              <tr>\r\n                <th>Data/Hora Atualização</th>\r\n                <th>Arquivo Origem</th>\r\n                <th>Total Embarques</th>\r\n                <th>Total Paletes Base</th>\r\n                <th>Alterações Detectadas</th>\r\n              </tr>\r\n            </thead>\r\n            <tbody id=\"tableEvolucaoBody\"></tbody>\r\n          </table>\r\n        </div>\r\n\r\n        <div style=\"display: flex; justify-content: flex-end; align-items: center; margin-top: 16px; border-top: 1px solid var(--border-light); padding-top: 12px;\">\r\n          <button class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 20px;\" data-csp-onclick=\"document.getElementById('modalHistorico').style.display='none'\">\r\n            Fechar\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 3: INFORMAÇÕES DA BASE\r\n       ========================================================= -->\r\n  <div id=\"modalBase\" class=\"modal-backdrop\">\r\n    <div class=\"modal-clean-box\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; border-bottom: 1px solid var(--border-light); padding-bottom: 12px;\">\r\n        <h2 style=\"font-size: 1.1rem; font-weight: 800; color: var(--text-primary);\">Base de Dados de Alocação</h2>\r\n        <button id=\"btnCloseModalBase\" class=\"btn-close-x\">&times;</button>\r\n      </div>\r\n      <div id=\"infoBaseDetails\" style=\"font-size: 0.9rem; color: var(--text-secondary); line-height: 1.5; margin-bottom: 16px;\">\r\n        Carregando informações da base...\r\n      </div>\r\n      <div style=\"background: #F8FAFC; border: 1px solid var(--border-light); border-radius: 8px; padding: 14px; margin-bottom: 16px;\">\r\n        <div style=\"font-size: 0.75rem; font-weight: 700; color: var(--text-muted); text-transform: uppercase;\">Como a base é atualizada:</div>\r\n        <div style=\"font-size: 0.88rem; color: var(--text-primary); margin-top: 6px; line-height: 1.5;\">\r\n          <b>Opção 1 (Automático em Nuvem / GitHub):</b> O GitHub Actions conecta no Azure SQL na view <code>[itatiaia].[SHIPPING_PCKWRK_VIEW_SIMPLIFICADA]</code> de forma 100% autônoma, sem necessidade de arquivos .bat.<br><br>\r\n          <b>Opção 2 (Upload Direto no Navegador):</b> Arraste o arquivo Excel (<b>adhoc80.xlsx</b> ou planilha WMS) na opção <b>\"Atualizar Base\"</b> na barra superior.\r\n        </div>\r\n      </div>\r\n      <div style=\"display: flex; justify-content: flex-end;\">\r\n        <button id=\"btnFecharModalBase\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 18px;\">Fechar</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 4: CONCLUSÃO / RESUMO DA CONFERÊNCIA\r\n       ========================================================= -->\r\n  <div id=\"modalRelatorio\" class=\"modal-backdrop\">\r\n    <div class=\"modal-clean-box\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; border-bottom: 1px solid var(--border-light); padding-bottom: 12px;\">\r\n        <h2 style=\"font-size: 1.1rem; font-weight: 800; color: var(--text-primary);\">Resumo da Conferência</h2>\r\n        <button id=\"btnCloseModal\" class=\"btn-close-x\">&times;</button>\r\n      </div>\r\n      <div id=\"modalBody\"></div>\r\n      <div style=\"display: flex; justify-content: flex-end; gap: 10px; margin-top: 24px;\">\r\n        <button id=\"btnPrintModal\" class=\"btn-secondary-clean\" style=\"margin-left: 0;\">Imprimir</button>\r\n        <button id=\"btnOkModal\" class=\"btn-finish-clean\">Salvar & Concluir</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 5: CONFIGURAÇÕES DE SINCRONIZAÇÃO EM TEMPO REAL (ON-TIME)\r\n       ========================================================= -->\r\n  <div id=\"modalSyncConfig\" class=\"modal-backdrop\" style=\"display: none;\">\r\n    <div class=\"modal-clean-box\" style=\"max-width: 520px; border-top: 4px solid #10B981;\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; border-bottom: 1.5px solid #F1F5F9; padding-bottom: 10px;\">\r\n        <div style=\"display: flex; align-items: center; gap: 8px;\">\r\n          <span style=\"font-size: 1.5rem;\">📡</span>\r\n          <div>\r\n            <h2 style=\"font-size: 1.15rem; font-weight: 800; color: #0F172A; margin: 0;\">Sincronização em Tempo Real (On-Time)</h2>\r\n            <span style=\"font-size: 0.76rem; color: #64748B;\">Multi-usuário automático • GitHub Pages, Coletores e Laptops</span>\r\n          </div>\r\n        </div>\r\n        <button type=\"button\" class=\"btn-close-x\" data-csp-onclick=\"document.getElementById('modalSyncConfig').style.display='none'\">&times;</button>\r\n      </div>\r\n\r\n      <div id=\"syncModalStatusDesc\" style=\"background: #F0FDF4; border: 1px solid #BBF7D0; border-radius: 8px; padding: 12px; margin-bottom: 14px; font-size: 0.85rem; color: #166534; line-height: 1.4;\">\r\n        🟢 Conectado em Tempo Real (On-Time) via WebSockets\r\n      </div>\r\n\r\n      <div style=\"background: #F8FAFC; border: 1px solid #E2E8F0; border-radius: 8px; padding: 14px; margin-bottom: 16px;\">\r\n        <label for=\"inputSyncRoom\" style=\"font-weight: 700; color: #1E293B; font-size: 0.82rem; display: block; margin-bottom: 6px;\">\r\n          🏷️ Canal / Sala de Operação (Compartilhado):\r\n        </label>\r\n        <div style=\"display: flex; gap: 8px;\">\r\n          <input type=\"text\" id=\"inputSyncRoom\" class=\"input-clean\" style=\"font-weight: 800; color: #0F172A;\" placeholder=\"Ex: PG_ITATIAIA_EXPEDICAO\">\r\n          <button type=\"button\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 16px;\" data-csp-onclick=\"salvarCanalSync()\">\r\n            Salvar Canal\r\n          </button>\r\n        </div>\r\n        <span style=\"font-size: 0.72rem; color: #64748B; margin-top: 4px; display: block;\">\r\n          Todos os aparelhos (celulares, coletores e PCs) que usarem o mesmo canal receberão as bipagens e alterações instantaneamente.\r\n        </span>\r\n      </div>\r\n\r\n      <div style=\"margin-bottom: 16px;\">\r\n        <div style=\"font-size: 0.8rem; font-weight: 800; color: #475569; text-transform: uppercase; margin-bottom: 8px;\">\r\n          Dispositivos Ativos Neste Canal:\r\n        </div>\r\n        <ul id=\"syncPeersList\" style=\"list-style: none; padding: 0; margin: 0; font-size: 0.82rem; max-height: 120px; overflow-y: auto;\">\r\n          <li style=\"color: #64748B;\">Carregando operadores ativos...</li>\r\n        </ul>\r\n      </div>\r\n\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; border-top: 1px solid #E2E8F0; padding-top: 12px;\">\r\n        <button type=\"button\" class=\"btn-secondary-clean\" style=\"margin-left: 0; font-size: 0.8rem;\" data-csp-onclick=\"forcarSincronizacaoGeral()\">\r\n          🔄 Transmitir Minha Sessão para Todos\r\n        </button>\r\n        <button type=\"button\" class=\"btn-clean-primary\" style=\"margin-top: 0; width: auto; padding: 8px 18px;\" data-csp-onclick=\"document.getElementById('modalSyncConfig').style.display='none'\">\r\n          Fechar\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- =========================================================\r\n       MODAL 6: VISUALIZADOR EMBED DO POWER BI AD HOC 80\r\n       ========================================================= -->\r\n  <div id=\"modalPowerBiIframe\" class=\"modal-backdrop\" style=\"display: none;\">\r\n    <div class=\"modal-clean-box\" style=\"max-width: 95vw; width: 1240px; height: 90vh; display: flex; flex-direction: column; padding: 16px;\">\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; border-bottom: 1px solid var(--border-light); padding-bottom: 10px;\">\r\n        <div style=\"display: flex; align-items: center; gap: 10px;\">\r\n          <span style=\"font-size: 1.5rem;\">📊</span>\r\n          <div>\r\n            <h2 style=\"font-size: 1.15rem; font-weight: 800; color: #003DA5; margin: 0;\">AD HOC 80 — Power BI Oficial CD Itatiaia</h2>\r\n            <span style=\"font-size: 0.76rem; color: #64748B;\">Relatório oficial de alocação de paletes e embarques da view WMS</span>\r\n          </div>\r\n        </div>\r\n        <div style=\"display: flex; gap: 8px; align-items: center;\">\r\n          <a href=\"https://app.powerbi.com/groups/me/reports/3cf5dcbd-f996-4d3e-afd5-564fbf1a6761/9d415a94aa4fce655114?ctid=3596192b-fdf5-4e2c-a6fa-acb706c963d8&amp;experience=power-bi\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"btn-clean-primary\" style=\"margin: 0; width: auto; padding: 6px 14px; background: #003DA5; font-size: 0.8rem; text-decoration: none; display: inline-flex; align-items: center; gap: 4px; font-weight: 700;\">\r\n            🔗 Abrir em Nova Guia ↗\r\n          </a>\r\n          <button type=\"button\" class=\"btn-close-x\" data-csp-onclick=\"fecharModalPowerBiIframe()\">&times;</button>\r\n        </div>\r\n      </div>\r\n\r\n      <div style=\"flex: 1; position: relative; border-radius: 8px; overflow: hidden; background: #0F172A; min-height: 400px; border: 1px solid #CBD5E1;\">\r\n        <iframe id=\"iframePowerBi\" src=\"\" style=\"width: 100%; height: 100%; border: none;\" allowfullscreen=\"true\"></iframe>\r\n      </div>\r\n\r\n      <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 12px; font-size: 0.78rem; color: #64748B; flex-wrap: wrap; gap: 8px;\">\r\n        <div>\r\n          💡 <b>Para extrair os dados atualizados:</b> No Power BI, clique com o botão direito na tabela de dados &gt; <b>Exportar dados</b> &gt; selecione <b>\"Dados com layout atual\"</b> ou <b>\".xlsx (Excel 150.000 linhas)\"</b>. Depois, arraste o arquivo na opção <i>\"Atualizar Base\"</i>.\r\n        </div>\r\n        <button type=\"button\" class=\"btn-clean-primary\" style=\"margin: 0; width: auto; padding: 6px 18px;\" data-csp-onclick=\"fecharModalPowerBiIframe()\">\r\n          Fechar\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Toast Notification Flutuante -->\r\n  <div id=\"toastNotification\" class=\"toast-box\"></div>\r\n\r\n  <!-- Bibliotecas: MQTT para sincronização em tempo real na nuvem/GitHub e SheetJS para Excel -->\r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n  \r\n",
        '</div>'
      ].join('');

