  activeConference = {
    embarqueId: activeEmbarque.embarque,
    operador: activeConference.operador,
    iniciadoEm: new Date(),
    finalizadoEm: null,
    conferidos: new Map(),
    divergencias: [],
    historico: [],
    currentPhysicalStage: initialPhysicalStage,
    lastComparison: null,
    stageSlots: {},
    slots: {},
    activeSlot: 1,
    capacity: stageCap,
    direction: 'asc'
  };
  recordActiveConferenceToHistory('Em Andamento');
  persistActiveSession();
  updateUI();
